//! Runtime of the chat templates generated by `jinja2rust`: Jinja's values and
//! the operations the templates use on them, with Python's semantics where
//! they show in the rendered text (`str()`, `json.dumps`, string methods).
//!
//! Strings remember where their text comes from: the template's own text
//! (its literals, [`Seg::lit`]) or the data it was given (messages, tools).
//! Concatenation and trimming keep the segments apart; any other operation
//! mixing the two gives data. Only the template's own text may hold special
//! tokens, so the rendered [`Str`] maps directly to the tokenizer's template
//! and content parts.
//!
//! `no_std` + `alloc`.

use alloc::borrow::ToOwned;
use alloc::format;
use alloc::rc::Rc;
use alloc::string::{String, ToString};
use alloc::vec;
use alloc::vec::Vec;
use core::cell::RefCell;
use core::fmt::Write;

/// A piece of text, the template's own or from the data
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Seg {
    pub text: String,
    /// the template's own text: special token strings in it are tokens
    pub lit: bool,
}

/// A string of segments, adjacent segments of the same origin merged
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Str(pub Vec<Seg>);

impl Str {
    pub fn lit(s: &str) -> Str {
        let mut out = Str::default();
        out.push(s, true);
        out
    }

    pub fn data(s: &str) -> Str {
        let mut out = Str::default();
        out.push(s, false);
        out
    }

    pub fn push(&mut self, s: &str, lit: bool) {
        if s.is_empty() {
            return;
        }
        match self.0.last_mut() {
            Some(last) if last.lit == lit => last.text.push_str(s),
            _ => self.0.push(Seg {
                text: s.to_owned(),
                lit,
            }),
        }
    }

    pub fn push_str(&mut self, other: &Str) {
        for seg in &other.0 {
            self.push(&seg.text, seg.lit);
        }
    }

    /// the template's own text only
    pub fn is_lit(&self) -> bool {
        self.0.iter().all(|s| s.lit)
    }

    pub fn text(&self) -> String {
        let mut t = String::new();
        for seg in &self.0 {
            t.push_str(&seg.text);
        }
        t
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    /// Text computed from this string: the template's own if this is
    fn derived(&self, text: &str) -> Str {
        let mut out = Str::default();
        out.push(text, self.is_lit());
        out
    }

    fn strip(&self, start: bool, end: bool, pred: impl Fn(char) -> bool) -> Str {
        let mut segs = self.0.clone();
        if start {
            while let Some(first) = segs.first_mut() {
                let t = first.text.trim_start_matches(&pred);
                if t.is_empty() {
                    segs.remove(0);
                } else {
                    first.text = t.to_owned();
                    break;
                }
            }
        }
        if end {
            while let Some(last) = segs.last_mut() {
                let t = last.text.trim_end_matches(&pred);
                if t.is_empty() {
                    segs.pop();
                } else {
                    last.text = t.to_owned();
                    break;
                }
            }
        }
        Str(segs)
    }
}

pub type Map = Vec<(String, Value)>;

#[derive(Clone, Debug, Default)]
pub enum Value {
    #[default]
    Undefined,
    None,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(Str),
    List(Rc<Vec<Value>>),
    /// a mapping, in insertion order as Python's dicts
    Map(Rc<Map>),
    /// a `namespace()`, the only mutable value
    Ns(Rc<RefCell<Map>>),
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Error(pub String);

pub type R<T = Value> = Result<T, Error>;

fn err<T>(msg: impl Into<String>) -> R<T> {
    Err(Error(msg.into()))
}

impl Value {
    pub fn lit(s: &str) -> Value {
        Value::Str(Str::lit(s))
    }

    pub fn data(s: &str) -> Value {
        Value::Str(Str::data(s))
    }

    pub fn list(items: Vec<Value>) -> Value {
        Value::List(Rc::new(items))
    }

    pub fn map(entries: Vec<(&str, Value)>) -> Value {
        Value::Map(Rc::new(
            entries
                .into_iter()
                .map(|(k, v)| (k.to_owned(), v))
                .collect(),
        ))
    }

    pub fn is_undefined(&self) -> bool {
        matches!(self, Value::Undefined)
    }

    fn type_name(&self) -> &'static str {
        match self {
            Value::Undefined => "undefined",
            Value::None => "none",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::List(_) => "list",
            Value::Map(_) => "mapping",
            Value::Ns(_) => "namespace",
        }
    }
}

/// 64-bit FNV-1a, the hash that recognizes a template by its text
pub fn fnv1a(s: &str) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in s.bytes() {
        h ^= b as u64;
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    h
}

// ---------------------------------------------------------------------------
// conversions

/// Jinja's truthiness, Python's
pub fn truthy(v: &Value) -> bool {
    match v {
        Value::Undefined | Value::None => false,
        Value::Bool(b) => *b,
        Value::Int(i) => *i != 0,
        Value::Float(f) => *f != 0.0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.is_empty(),
        Value::Map(m) => !m.is_empty(),
        Value::Ns(_) => true,
    }
}

/// `str(v)`, as Jinja prints a value
pub fn to_str(v: &Value) -> Str {
    match v {
        Value::Undefined => Str::default(),
        Value::Str(s) => s.clone(),
        other => {
            let mut t = String::new();
            repr_into(other, false, &mut t);
            Str::data(&t)
        }
    }
}

/// Python's `repr()`, or `str()` at the top when `quote` is false
fn repr_into(v: &Value, quote: bool, out: &mut String) {
    match v {
        Value::Undefined => {}
        Value::None => out.push_str("None"),
        Value::Bool(true) => out.push_str("True"),
        Value::Bool(false) => out.push_str("False"),
        Value::Int(i) => {
            let _ = write!(out, "{i}");
        }
        Value::Float(f) => py_float(*f, out),
        Value::Str(s) if !quote => out.push_str(&s.text()),
        Value::Str(s) => {
            let t = s.text();
            let q = if t.contains('\'') && !t.contains('"') {
                '"'
            } else {
                '\''
            };
            out.push(q);
            for c in t.chars() {
                match c {
                    '\\' => out.push_str("\\\\"),
                    '\n' => out.push_str("\\n"),
                    '\r' => out.push_str("\\r"),
                    '\t' => out.push_str("\\t"),
                    c if c == q => {
                        out.push('\\');
                        out.push(c);
                    }
                    c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                        let _ = write!(out, "\\x{:02x}", c as u32);
                    }
                    c => out.push(c),
                }
            }
            out.push(q);
        }
        Value::List(l) => {
            out.push('[');
            for (i, x) in l.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                repr_into(x, true, out);
            }
            out.push(']');
        }
        Value::Map(m) => repr_map(m, out),
        Value::Ns(m) => {
            out.push_str("<Namespace ");
            repr_map(&m.borrow(), out);
            out.push('>');
        }
    }
}

fn repr_map(m: &Map, out: &mut String) {
    out.push('{');
    for (i, (k, x)) in m.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        repr_into(&Value::data(k), true, out);
        out.push_str(": ");
        repr_into(x, true, out);
    }
    out.push('}');
}

/// Python's `repr()` of a float: the shortest digits that round-trip, in
/// exponent form below 1e-4 and from 1e16
fn py_float(f: f64, out: &mut String) {
    if f.is_nan() {
        out.push_str("nan");
        return;
    }
    if f.is_infinite() {
        out.push_str(if f > 0.0 { "inf" } else { "-inf" });
        return;
    }
    // Rust's `{:e}` gives the shortest round-trip digits: "-1.2345e-7"
    let e = format!("{f:e}");
    let (mantissa, exp) = e.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let (neg, mantissa) = match mantissa.strip_prefix('-') {
        Some(m) => (true, m),
        None => (false, mantissa),
    };
    let mut digits: String = mantissa.chars().filter(|c| *c != '.').collect();
    let mut exp = exp;
    even_tie(f.abs(), &mut digits, &mut exp);
    if neg {
        out.push('-');
    }
    if (-4..16).contains(&exp) {
        let point = exp + 1;
        if point <= 0 {
            out.push_str("0.");
            for _ in 0..-point {
                out.push('0');
            }
            out.push_str(&digits);
        } else if point as usize >= digits.len() {
            out.push_str(&digits);
            for _ in digits.len()..point as usize {
                out.push('0');
            }
            out.push_str(".0");
        } else {
            out.push_str(&digits[..point as usize]);
            out.push('.');
            out.push_str(&digits[point as usize..]);
        }
    } else {
        out.push_str(&digits[..1]);
        if digits.len() > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        let _ = write!(out, "e{}{:02}", if exp < 0 { '-' } else { '+' }, exp.abs());
    }
}

/// When `f` (positive) is exactly halfway between two shortest digit strings
/// that round-trip, Python's `repr()` takes the one that ends in an even
/// digit, and Rust's `{:e}` the larger: `digits` (no point, no trailing
/// zeros) at `exp`, Rust's, become Python's
fn even_tie(f: f64, digits: &mut String, exp: &mut i32) {
    let n = digits.len();
    // a tie's next digit is a 5, and the last
    let near = format!("{f:.n$e}");
    if !near.split_once('e').is_some_and(|(m, _)| m.ends_with('5')) {
        return;
    }
    // exactly: a double's expansion has at most 767 significant digits
    let exact = format!("{f:.800e}");
    let (m, e) = exact.split_once('e').unwrap();
    let all: String = m.chars().filter(|c| *c != '.').collect();
    let all = all.trim_end_matches('0');
    if all.len() != n + 1 || !all.ends_with('5') {
        return;
    }
    let e: i32 = e.parse().unwrap();
    // the two candidates, n digits each
    let lo = (all[..n].to_string(), e);
    let mut hi = all.as_bytes()[..n].to_vec();
    let mut i = n;
    while i > 0 && hi[i - 1] == b'9' {
        hi[i - 1] = b'0';
        i -= 1;
    }
    let hi = if i == 0 {
        (format!("1{}", "0".repeat(n - 1)), e + 1)
    } else {
        hi[i - 1] += 1;
        (String::from_utf8(hi).unwrap(), e)
    };
    let round_trips = |(d, e): &(String, i32)| format!("{d}e{}", e + 1 - n as i32).parse() == Ok(f);
    if !round_trips(&lo) || !round_trips(&hi) {
        return;
    }
    let (d, e) = if lo.0.as_bytes()[n - 1].is_multiple_of(2) {
        lo
    } else {
        hi
    };
    // the first digit isn't a zero
    *digits = d.trim_end_matches('0').into();
    *exp = e;
}

/// `{{ v }}`
pub fn emit(out: &mut Str, v: &Value) {
    out.push_str(&to_str(v));
}

// ---------------------------------------------------------------------------
// access

/// `v.name`: a key of a mapping, or undefined
pub fn getattr(v: &Value, name: &str) -> Value {
    match v {
        Value::Map(m) => lookup(m, name),
        Value::Ns(m) => lookup(&m.borrow(), name),
        _ => Value::Undefined,
    }
}

fn lookup(m: &Map, name: &str) -> Value {
    m.iter()
        .find(|(k, _)| k == name)
        .map(|(_, v)| v.clone())
        .unwrap_or_default()
}

/// `ns.name = value`
pub fn set_attr(ns: &Value, name: &str, value: Value) -> R<()> {
    let Value::Ns(m) = ns else {
        return err(format!("cannot set an attribute of a {}", ns.type_name()));
    };
    let mut m = m.borrow_mut();
    match m.iter_mut().find(|(k, _)| k == name) {
        Some((_, v)) => *v = value,
        None => m.push((name.to_owned(), value)),
    }
    Ok(())
}

/// `v[index]`: undefined when out of range or missing, as in Jinja
pub fn getitem(v: &Value, index: &Value) -> R {
    Ok(match (v, index) {
        (Value::List(l), Value::Int(i)) => {
            let i = if *i < 0 { l.len() as i64 + i } else { *i };
            if i < 0 {
                Value::Undefined
            } else {
                l.get(i as usize).cloned().unwrap_or_default()
            }
        }
        (Value::Str(s), Value::Int(i)) => {
            let chars: Vec<char> = s.text().chars().collect();
            let i = if *i < 0 { chars.len() as i64 + i } else { *i };
            match (i >= 0).then(|| chars.get(i as usize)).flatten() {
                Some(c) => Value::Str(s.derived(c.encode_utf8(&mut [0; 4]))),
                None => Value::Undefined,
            }
        }
        (Value::Map(_) | Value::Ns(_), Value::Str(k)) => getattr(v, &k.text()),
        (Value::Undefined, _) => Value::Undefined,
        _ => {
            return err(format!(
                "cannot index a {} with a {}",
                v.type_name(),
                index.type_name()
            ));
        }
    })
}

/// Python's slice indices, for a sequence of `len`
fn slice_indices(len: usize, start: &Value, stop: &Value, step: &Value) -> R<Vec<usize>> {
    let int = |v: &Value| -> R<Option<i64>> {
        match v {
            Value::Undefined | Value::None => Ok(None),
            Value::Int(i) => Ok(Some(*i)),
            other => err(format!(
                "slice index must be an int, not {}",
                other.type_name()
            )),
        }
    };
    let len = len as i64;
    let step = int(step)?.unwrap_or(1);
    if step == 0 {
        return err("slice step cannot be zero");
    }
    let clamp = |i: i64, lo: i64, hi: i64| {
        let i = if i < 0 { i + len } else { i };
        i.clamp(lo, hi)
    };
    let mut out = Vec::new();
    if step > 0 {
        let start = int(start)?.map_or(0, |i| clamp(i, 0, len));
        let stop = int(stop)?.map_or(len, |i| clamp(i, 0, len));
        let mut i = start;
        while i < stop {
            out.push(i as usize);
            i += step;
        }
    } else {
        let start = int(start)?.map_or(len - 1, |i| clamp(i, -1, len - 1));
        let stop = int(stop)?.map_or(-1, |i| clamp(i, -1, len - 1));
        let mut i = start;
        while i > stop {
            out.push(i as usize);
            i += step;
        }
    }
    Ok(out)
}

/// `v[start:stop:step]`
pub fn slice(v: &Value, start: &Value, stop: &Value, step: &Value) -> R {
    match v {
        Value::List(l) => Ok(Value::list(
            slice_indices(l.len(), start, stop, step)?
                .into_iter()
                .map(|i| l[i].clone())
                .collect(),
        )),
        Value::Str(s) => {
            let chars: Vec<char> = s.text().chars().collect();
            let t: String = slice_indices(chars.len(), start, stop, step)?
                .into_iter()
                .map(|i| chars[i])
                .collect();
            Ok(Value::Str(s.derived(&t)))
        }
        Value::Undefined => Ok(Value::Undefined),
        other => err(format!("cannot slice a {}", other.type_name())),
    }
}

/// The items `for` goes through: a list's items, a mapping's keys, a
/// string's characters; none for undefined
pub fn iter(v: &Value) -> R<Vec<Value>> {
    Ok(match v {
        Value::List(l) => l.as_ref().clone(),
        Value::Map(m) => m.iter().map(|(k, _)| Value::data(k)).collect(),
        Value::Str(s) => s
            .text()
            .chars()
            .map(|c| Value::Str(s.derived(c.encode_utf8(&mut [0; 4]))))
            .collect(),
        Value::Undefined => Vec::new(),
        other => return err(format!("cannot iterate over a {}", other.type_name())),
    })
}

/// `for a, b in ...`
pub fn unpack(v: &Value, n: usize) -> R<Vec<Value>> {
    let items = iter(v)?;
    if items.len() != n {
        return err(format!("cannot unpack {} values into {n}", items.len()));
    }
    Ok(items)
}

/// The `loop` variable at item `i` of `items`
pub fn loop_info(items: &[Value], i: usize) -> Value {
    let n = items.len();
    let mut m: Map = vec![
        ("index0".into(), Value::Int(i as i64)),
        ("index".into(), Value::Int(i as i64 + 1)),
        ("revindex0".into(), Value::Int((n - i - 1) as i64)),
        ("revindex".into(), Value::Int((n - i) as i64)),
        ("first".into(), Value::Bool(i == 0)),
        ("last".into(), Value::Bool(i + 1 == n)),
        ("length".into(), Value::Int(n as i64)),
    ];
    if i > 0 {
        m.push(("previtem".into(), items[i - 1].clone()));
    }
    if i + 1 < n {
        m.push(("nextitem".into(), items[i + 1].clone()));
    }
    Value::Map(Rc::new(m))
}

// ---------------------------------------------------------------------------
// operators

fn num(v: &Value) -> Option<f64> {
    match v {
        Value::Int(i) => Some(*i as f64),
        Value::Float(f) => Some(*f),
        Value::Bool(b) => Some(*b as i64 as f64),
        _ => None,
    }
}

fn int(v: &Value) -> Option<i64> {
    match v {
        Value::Int(i) => Some(*i),
        Value::Bool(b) => Some(*b as i64),
        _ => None,
    }
}

/// `a + b`
pub fn add(a: &Value, b: &Value) -> R {
    Ok(match (a, b) {
        (Value::Str(x), Value::Str(y)) => {
            let mut s = x.clone();
            s.push_str(y);
            Value::Str(s)
        }
        (Value::List(x), Value::List(y)) => {
            Value::list(x.iter().chain(y.iter()).cloned().collect())
        }
        _ => match (int(a), int(b)) {
            (Some(x), Some(y)) => Value::Int(x.wrapping_add(y)),
            _ => match (num(a), num(b)) {
                (Some(x), Some(y)) => Value::Float(x + y),
                _ => {
                    return err(format!(
                        "cannot add {} and {}",
                        a.type_name(),
                        b.type_name()
                    ));
                }
            },
        },
    })
}

/// `a ~ b`
pub fn concat(a: &Value, b: &Value) -> Value {
    let mut s = to_str(a);
    s.push_str(&to_str(b));
    Value::Str(s)
}

/// `a - b`, `a * b`, `a / b`, `a // b`, `a % b`, `a ** b`
pub fn arith(op: &str, a: &Value, b: &Value) -> R {
    if op == "*"
        && let (Value::Str(s), n) | (n, Value::Str(s)) = (a, b)
        && let Some(n) = int(n)
    {
        let t = s.text().repeat(n.max(0) as usize);
        return Ok(Value::Str(s.derived(&t)));
    }
    let bad = || {
        err(format!(
            "cannot {op} {} and {}",
            a.type_name(),
            b.type_name()
        ))
    };
    if op != "/"
        && let (Some(x), Some(y)) = (int(a), int(b))
    {
        return Ok(Value::Int(match op {
            "-" => x.wrapping_sub(y),
            "*" => x.wrapping_mul(y),
            "//" if y == 0 => return err("division by zero"),
            "//" => x / y - i64::from(x % y != 0 && (x < 0) != (y < 0)),
            "%" if y == 0 => return err("division by zero"),
            "%" => ((x % y) + y) % y,
            "**" if y >= 0 => x.wrapping_pow(y as u32),
            "**" => return Ok(Value::Float(powi(x as f64, y as f64))),
            _ => return bad(),
        }));
    }
    let (Some(x), Some(y)) = (num(a), num(b)) else {
        return bad();
    };
    Ok(Value::Float(match op {
        "-" => x - y,
        "*" => x * y,
        "/" | "//" | "%" if y == 0.0 => return err("division by zero"),
        "/" => x / y,
        "//" => floor(x / y),
        "%" => x - y * floor(x / y),
        "**" => powi(x, y),
        _ => return bad(),
    }))
}

fn floor(x: f64) -> f64 {
    let t = x as i64 as f64;
    if t > x { t - 1.0 } else { t }
}

/// `x ** y` for an integral `y`, all the templates use
fn powi(x: f64, y: f64) -> f64 {
    let mut r = 1.0;
    let n = y as i64;
    for _ in 0..n.unsigned_abs() {
        r *= x;
    }
    if n < 0 { 1.0 / r } else { r }
}

/// `-v`
pub fn neg(v: &Value) -> R {
    match v {
        Value::Int(i) => Ok(Value::Int(-i)),
        Value::Float(f) => Ok(Value::Float(-f)),
        other => err(format!("cannot negate a {}", other.type_name())),
    }
}

/// `a == b`
pub fn eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Undefined, Value::Undefined) | (Value::None, Value::None) => true,
        (Value::Str(x), Value::Str(y)) => x.text() == y.text(),
        (Value::List(x), Value::List(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| eq(a, b))
        }
        (Value::Map(x), Value::Map(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, v)| y.iter().any(|(k2, v2)| k == k2 && eq(v, v2)))
        }
        (Value::Ns(x), Value::Ns(y)) => Rc::ptr_eq(x, y),
        _ => match (num(a), num(b)) {
            (Some(x), Some(y)) => x == y,
            _ => false,
        },
    }
}

/// `a < b` and the other orderings: `op` is one of `<`, `<=`, `>`, `>=`
pub fn cmp(op: &str, a: &Value, b: &Value) -> R<bool> {
    use core::cmp::Ordering;
    let ord = match (a, b) {
        (Value::Str(x), Value::Str(y)) => Some(x.text().cmp(&y.text())),
        _ => match (num(a), num(b)) {
            (Some(x), Some(y)) => x.partial_cmp(&y),
            _ => {
                return err(format!(
                    "cannot compare {} and {}",
                    a.type_name(),
                    b.type_name()
                ));
            }
        },
    };
    let Some(ord) = ord else { return Ok(false) };
    Ok(match op {
        "<" => ord == Ordering::Less,
        "<=" => ord != Ordering::Greater,
        ">" => ord == Ordering::Greater,
        ">=" => ord != Ordering::Less,
        _ => return err(format!("unknown comparison {op}")),
    })
}

/// `item in container`
pub fn contains(container: &Value, item: &Value) -> R<bool> {
    Ok(match container {
        Value::Str(s) => match item {
            Value::Str(i) => s.text().contains(&i.text()),
            other => {
                return err(format!(
                    "'in <string>' requires a string, not {}",
                    other.type_name()
                ));
            }
        },
        Value::List(l) => l.iter().any(|x| eq(x, item)),
        Value::Map(m) => match item {
            Value::Str(k) => {
                let k = k.text();
                m.iter().any(|(key, _)| *key == k)
            }
            _ => false,
        },
        Value::Undefined => false,
        other => return err(format!("cannot look into a {}", other.type_name())),
    })
}

// ---------------------------------------------------------------------------
// tests: `v is name`

pub fn is_defined(v: &Value) -> bool {
    !v.is_undefined()
}
pub fn is_undefined(v: &Value) -> bool {
    v.is_undefined()
}
pub fn is_none(v: &Value) -> bool {
    matches!(v, Value::None)
}
pub fn is_string(v: &Value) -> bool {
    matches!(v, Value::Str(_))
}
pub fn is_mapping(v: &Value) -> bool {
    matches!(v, Value::Map(_) | Value::Ns(_))
}
/// Jinja's `iterable`; undefined is one, as jinja2's `Undefined` iterates
pub fn is_iterable(v: &Value) -> bool {
    matches!(
        v,
        Value::Str(_) | Value::List(_) | Value::Map(_) | Value::Undefined
    )
}
/// Jinja's `sequence`: anything with a length
pub fn is_sequence(v: &Value) -> bool {
    matches!(v, Value::Str(_) | Value::List(_) | Value::Map(_))
}
pub fn is_true(v: &Value) -> bool {
    matches!(v, Value::Bool(true))
}
pub fn is_false(v: &Value) -> bool {
    matches!(v, Value::Bool(false))
}
pub fn is_boolean(v: &Value) -> bool {
    matches!(v, Value::Bool(_))
}
pub fn is_number(v: &Value) -> bool {
    matches!(v, Value::Int(_) | Value::Float(_) | Value::Bool(_))
}
pub fn is_integer(v: &Value) -> bool {
    matches!(v, Value::Int(_) | Value::Bool(_))
}
pub fn is_float(v: &Value) -> bool {
    matches!(v, Value::Float(_))
}

// ---------------------------------------------------------------------------
// filters: `v | name(args)`

fn is_py_space(c: char) -> bool {
    c.is_whitespace()
}

/// `trim`, `strip()`, `lstrip()`, `rstrip()`: whitespace or the given characters
fn strip(v: &Value, chars: &Value, start: bool, end: bool) -> R {
    let s = to_str(v);
    Ok(Value::Str(match chars {
        Value::Undefined | Value::None => s.strip(start, end, is_py_space),
        Value::Str(c) => {
            let c = c.text();
            s.strip(start, end, |x| c.contains(x))
        }
        other => {
            return err(format!(
                "strip characters must be a string, not {}",
                other.type_name()
            ));
        }
    }))
}

pub fn f_trim(v: &Value, chars: &Value) -> R {
    strip(v, chars, true, true)
}

pub fn f_length(v: &Value) -> R {
    Ok(Value::Int(match v {
        Value::Str(s) => s.text().chars().count(),
        Value::List(l) => l.len(),
        Value::Map(m) => m.len(),
        Value::Undefined => 0,
        other => return err(format!("a {} has no length", other.type_name())),
    } as i64))
}

pub fn f_string(v: &Value) -> Value {
    Value::Str(to_str(v))
}

pub fn f_default(v: &Value, default: &Value, boolean: &Value) -> Value {
    if v.is_undefined() || (truthy(boolean) && !truthy(v)) {
        default.clone()
    } else {
        v.clone()
    }
}

pub fn f_items(v: &Value) -> R {
    match v {
        Value::Map(m) => Ok(Value::list(
            m.iter()
                .map(|(k, x)| Value::list(vec![Value::data(k), x.clone()]))
                .collect(),
        )),
        Value::Ns(m) => f_items(&Value::Map(Rc::new(m.borrow().clone()))),
        Value::Undefined => Ok(Value::list(Vec::new())),
        other => err(format!("a {} has no items", other.type_name())),
    }
}

/// `dictsort`: a mapping's `(key, value)` pairs, by key, the case of
/// string keys ignored unless `case_sensitive`, ties in their order
pub fn f_dictsort(v: &Value, case_sensitive: &Value) -> R {
    let mut pairs: Map = match v {
        Value::Map(m) => m.as_ref().clone(),
        Value::Ns(m) => m.borrow().clone(),
        other => return err(format!("a {} has no items to sort", other.type_name())),
    };
    if truthy(case_sensitive) {
        pairs.sort_by(|a, b| a.0.cmp(&b.0));
    } else {
        pairs.sort_by_cached_key(|p| p.0.to_lowercase());
    }
    Ok(Value::list(
        pairs
            .into_iter()
            .map(|(k, x)| Value::list(vec![Value::data(&k), x]))
            .collect(),
    ))
}

/// `float`: a number as a float, a string parsed as one, else `default`
/// (0.0)
pub fn f_float(v: &Value, default: &Value) -> R {
    let default = match default {
        Value::Undefined => Value::Float(0.0),
        d => d.clone(),
    };
    Ok(match v {
        Value::Bool(b) => Value::Float(if *b { 1.0 } else { 0.0 }),
        Value::Int(i) => Value::Float(*i as f64),
        Value::Float(f) => Value::Float(*f),
        Value::Str(s) => match s.text().trim_matches(is_py_space).parse::<f64>() {
            Ok(f) => Value::Float(f),
            Err(_) => default,
        },
        Value::Undefined => return err("float of an undefined value"),
        _ => default,
    })
}

pub fn f_replace(v: &Value, old: &Value, new: &Value) -> R {
    let s = to_str(v);
    let (old, new) = (to_str(old), to_str(new));
    let t = s.text().replace(&old.text(), &new.text());
    // the template's own text only when all three are
    let mut out = Str::default();
    out.push(&t, s.is_lit() && new.is_lit());
    Ok(Value::Str(out))
}

pub fn f_upper(v: &Value) -> Value {
    let s = to_str(v);
    Value::Str(s.derived(&s.text().to_uppercase()))
}

pub fn f_lower(v: &Value) -> Value {
    let s = to_str(v);
    Value::Str(s.derived(&s.text().to_lowercase()))
}

pub fn f_first(v: &Value) -> R {
    Ok(iter(v)?.into_iter().next().unwrap_or_default())
}

pub fn f_last(v: &Value) -> R {
    Ok(iter(v)?.pop().unwrap_or_default())
}

pub fn f_list(v: &Value) -> R {
    Ok(Value::list(iter(v)?))
}

pub fn f_join(v: &Value, sep: &Value) -> R {
    let sep = to_str(sep);
    let mut out = Str::default();
    for (i, x) in iter(v)?.iter().enumerate() {
        if i > 0 {
            out.push_str(&sep);
        }
        out.push_str(&to_str(x));
    }
    Ok(Value::Str(out))
}

/// `tojson`, as transformers' chat templates have it: `json.dumps` with
/// `ensure_ascii=False`, `sort_keys=False` by default
pub fn f_tojson(v: &Value, ensure_ascii: &Value, indent: &Value, sort_keys: &Value) -> R {
    // Python's default separators
    let item_sep = match indent {
        Value::Undefined | Value::None => ", ",
        _ => ",",
    };
    f_tojson_sep(v, ensure_ascii, indent, sort_keys, item_sep, ": ")
}

/// [`f_tojson`] with `separators=(item_sep, key_sep)`
pub fn f_tojson_sep(
    v: &Value,
    ensure_ascii: &Value,
    indent: &Value,
    sort_keys: &Value,
    item_sep: &str,
    key_sep: &str,
) -> R {
    let indent = match indent {
        Value::Undefined | Value::None => None,
        Value::Int(i) => Some(*i.max(&0) as usize),
        other => {
            return err(format!(
                "tojson indent must be an int, not {}",
                other.type_name()
            ));
        }
    };
    let mut out = String::new();
    let opts = JsonOpts {
        ensure_ascii: truthy(ensure_ascii),
        indent,
        sort_keys: truthy(sort_keys),
        item_sep,
        key_sep,
    };
    json_into(v, &opts, 0, &mut out)?;
    Ok(Value::data(&out))
}

struct JsonOpts<'a> {
    ensure_ascii: bool,
    indent: Option<usize>,
    sort_keys: bool,
    /// between items, and between a key and its value
    item_sep: &'a str,
    key_sep: &'a str,
}

fn json_into(v: &Value, o: &JsonOpts, depth: usize, out: &mut String) -> R<()> {
    let newline = |out: &mut String, depth: usize| {
        if let Some(n) = o.indent {
            out.push('\n');
            for _ in 0..n * depth {
                out.push(' ');
            }
        }
    };
    match v {
        Value::None => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Int(i) => {
            let _ = write!(out, "{i}");
        }
        Value::Float(f) if f.is_nan() => out.push_str("NaN"),
        Value::Float(f) if f.is_infinite() => {
            out.push_str(if *f > 0.0 { "Infinity" } else { "-Infinity" })
        }
        Value::Float(f) => py_float(*f, out),
        Value::Str(s) => json_string(&s.text(), o.ensure_ascii, out),
        Value::List(l) => {
            if l.is_empty() {
                out.push_str("[]");
                return Ok(());
            }
            out.push('[');
            for (i, x) in l.iter().enumerate() {
                if i > 0 {
                    out.push_str(o.item_sep);
                }
                newline(out, depth + 1);
                json_into(x, o, depth + 1, out)?;
            }
            newline(out, depth);
            out.push(']');
        }
        Value::Map(m) => json_map(m, o, depth, out)?,
        Value::Ns(m) => json_map(&m.borrow(), o, depth, out)?,
        Value::Undefined => return err("undefined is not JSON serializable"),
    }
    Ok(())
}

fn json_map(m: &Map, o: &JsonOpts, depth: usize, out: &mut String) -> R<()> {
    if m.is_empty() {
        out.push_str("{}");
        return Ok(());
    }
    let mut entries: Vec<&(String, Value)> = m.iter().collect();
    if o.sort_keys {
        entries.sort_by(|a, b| a.0.cmp(&b.0));
    }
    out.push('{');
    for (i, (k, x)) in entries.into_iter().enumerate() {
        if i > 0 {
            out.push_str(o.item_sep);
        }
        if let Some(n) = o.indent {
            out.push('\n');
            for _ in 0..n * (depth + 1) {
                out.push(' ');
            }
        }
        json_string(k, o.ensure_ascii, out);
        out.push_str(o.key_sep);
        json_into(x, o, depth + 1, out)?;
    }
    if let Some(n) = o.indent {
        out.push('\n');
        for _ in 0..n * depth {
            out.push(' ');
        }
    }
    out.push('}');
    Ok(())
}

/// A JSON string as Python's `json.dumps` writes it
fn json_string(s: &str, ensure_ascii: bool, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c if ensure_ascii && (c as u32) > 0x7e => {
                let mut buf = [0u16; 2];
                for u in c.encode_utf16(&mut buf) {
                    let _ = write!(out, "\\u{u:04x}");
                }
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

// ---------------------------------------------------------------------------
// methods: `v.name(args)`

pub fn call_method(v: &Value, name: &str, args: &[Value]) -> R {
    let arg = |i: usize| args.get(i).cloned().unwrap_or_default();
    match (v, name) {
        (Value::Str(s), "startswith" | "endswith") => {
            let t = s.text();
            let test = |p: &Value| match p {
                Value::Str(p) => {
                    let p = p.text();
                    Ok(if name == "startswith" {
                        t.starts_with(&p)
                    } else {
                        t.ends_with(&p)
                    })
                }
                other => err(format!("{name} needs a string, not {}", other.type_name())),
            };
            let r = match arg(0) {
                Value::List(l) => {
                    let mut any = false;
                    for p in l.iter() {
                        any |= test(p)?;
                    }
                    any
                }
                p => test(&p)?,
            };
            Ok(Value::Bool(r))
        }
        (Value::Str(_), "strip") => strip(v, &arg(0), true, true),
        (Value::Str(_), "lstrip") => strip(v, &arg(0), true, false),
        (Value::Str(_), "rstrip") => strip(v, &arg(0), false, true),
        (Value::Str(_), "upper") => Ok(f_upper(v)),
        (Value::Str(_), "lower") => Ok(f_lower(v)),
        (Value::Str(_), "replace") => f_replace(v, &arg(0), &arg(1)),
        (Value::Str(s), "split" | "rsplit") => {
            let t = s.text();
            let maxsplit = match arg(1) {
                Value::Int(n) if n >= 0 => Some(n as usize),
                _ => None,
            };
            let parts: Vec<String> = match arg(0) {
                Value::Undefined | Value::None => {
                    let words = t.split_whitespace().map(|w| w.to_owned());
                    match maxsplit {
                        // rare enough: Python keeps the rest unsplit
                        Some(_) => return err("split() with maxsplit and no separator"),
                        None => words.collect(),
                    }
                }
                Value::Str(sep) => {
                    let sep = sep.text();
                    if sep.is_empty() {
                        return err("empty separator");
                    }
                    match (name, maxsplit) {
                        ("split", Some(n)) => t
                            .splitn(n + 1, sep.as_str())
                            .map(|x| x.to_owned())
                            .collect(),
                        ("split", None) => t.split(sep.as_str()).map(|x| x.to_owned()).collect(),
                        (_, Some(n)) => {
                            let mut p: Vec<String> = t
                                .rsplitn(n + 1, sep.as_str())
                                .map(|x| x.to_owned())
                                .collect();
                            p.reverse();
                            p
                        }
                        (_, None) => t.split(sep.as_str()).map(|x| x.to_owned()).collect(),
                    }
                }
                other => {
                    return err(format!(
                        "split separator must be a string, not {}",
                        other.type_name()
                    ));
                }
            };
            Ok(Value::list(
                parts.iter().map(|p| Value::Str(s.derived(p))).collect(),
            ))
        }
        (Value::Map(_) | Value::Ns(_), "items") => f_items(v),
        (Value::Map(m), "keys") => Ok(Value::list(m.iter().map(|(k, _)| Value::data(k)).collect())),
        (Value::Map(m), "values") => Ok(Value::list(m.iter().map(|(_, x)| x.clone()).collect())),
        (Value::Map(_), "get") => {
            let k = to_str(&arg(0)).text();
            Ok(match getattr(v, &k) {
                Value::Undefined => match arg(1) {
                    Value::Undefined => Value::None,
                    d => d,
                },
                x => x,
            })
        }
        _ => err(format!("a {} has no method {name}", v.type_name())),
    }
}

// ---------------------------------------------------------------------------
// functions

pub fn namespace(kwargs: Vec<(&str, Value)>) -> Value {
    Value::Ns(Rc::new(RefCell::new(
        kwargs.into_iter().map(|(k, v)| (k.to_owned(), v)).collect(),
    )))
}

pub fn raise_exception(msg: &Value) -> R {
    err(to_str(msg).text())
}

pub fn range(args: &[Value]) -> R {
    let int = |v: &Value| match v {
        Value::Int(i) => Ok(*i),
        other => err(format!("range needs ints, not {}", other.type_name())),
    };
    let (start, stop, step) = match args {
        [stop] => (0, int(stop)?, 1),
        [start, stop] => (int(start)?, int(stop)?, 1),
        [start, stop, step] => (int(start)?, int(stop)?, int(step)?),
        _ => return err("range takes 1 to 3 arguments"),
    };
    if step == 0 {
        return err("range step cannot be zero");
    }
    let mut out = Vec::new();
    let mut i = start;
    while (step > 0 && i < stop) || (step < 0 && i > stop) {
        out.push(Value::Int(i));
        i += step;
    }
    Ok(Value::list(out))
}

// ---------------------------------------------------------------------------
// the template's data, as native types

/// A JSON value, as tools' schemas and function arguments are
#[derive(Clone, Debug, PartialEq)]
pub enum Json {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<Json>),
    /// in order, as Python's dicts
    Object(Vec<(String, Json)>),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Role {
    System,
    Developer,
    User,
    Assistant,
    Tool,
}

impl Role {
    pub fn as_str(self) -> &'static str {
        match self {
            Role::System => "system",
            Role::Developer => "developer",
            Role::User => "user",
            Role::Assistant => "assistant",
            Role::Tool => "tool",
        }
    }

    pub fn parse(s: &str) -> Option<Role> {
        Some(match s {
            "system" => Role::System,
            "developer" => Role::Developer,
            "user" => Role::User,
            "assistant" => Role::Assistant,
            "tool" => Role::Tool,
            _ => return None,
        })
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub enum Content {
    #[default]
    None,
    Text(String),
    /// text, images and videos, in order
    Parts(Vec<Part>),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Part {
    Text(String),
    Image,
    Video,
}

/// A function call of an answer
#[derive(Clone, Debug, PartialEq)]
pub struct ToolCall {
    pub name: String,
    pub arguments: Vec<(String, Json)>,
}

/// A function the model may call
#[derive(Clone, Debug, PartialEq)]
pub struct Tool {
    pub name: String,
    pub description: Option<String>,
    /// the JSON schema of its arguments
    pub parameters: Json,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Message {
    pub role: Role,
    pub content: Content,
    /// an answer's reasoning, when kept apart from its content
    pub reasoning_content: Option<String>,
    /// an answer's function calls
    pub tool_calls: Vec<ToolCall>,
    /// who wrote it: the function a tool's result is of, as the template
    /// writes it. Not in `messages` when `None`.
    pub name: Option<String>,
}

impl Message {
    pub fn new(role: Role, text: &str) -> Message {
        Message {
            role,
            content: Content::Text(text.to_owned()),
            reasoning_content: None,
            tool_calls: Vec::new(),
            name: None,
        }
    }
}

/// `Json` as a template value, its strings data
pub fn json(j: &Json) -> Value {
    match j {
        Json::Null => Value::None,
        Json::Bool(b) => Value::Bool(*b),
        Json::Int(i) => Value::Int(*i),
        Json::Float(f) => Value::Float(*f),
        Json::Str(s) => Value::data(s),
        Json::Array(a) => Value::list(a.iter().map(json).collect()),
        Json::Object(o) => Value::Map(Rc::new(
            o.iter().map(|(k, v)| (k.clone(), json(v))).collect(),
        )),
    }
}

/// `messages`, in transformers' shape: `{"role", "content",
/// "reasoning_content", "name", "tool_calls": [{"type": "function",
/// "function": {"name", "arguments"}}]}`, the last three only when there are
/// some
pub fn messages(messages: &[Message]) -> Value {
    Value::list(
        messages
            .iter()
            .map(|m| {
                // the role is one of a few names: the template's own text
                let mut e: Map = vec![("role".into(), Value::lit(m.role.as_str()))];
                let content = match &m.content {
                    Content::None => Value::None,
                    Content::Text(t) => Value::data(t),
                    Content::Parts(parts) => Value::list(
                        parts
                            .iter()
                            .map(|p| match p {
                                Part::Text(t) => Value::map(vec![
                                    ("type", Value::lit("text")),
                                    ("text", Value::data(t)),
                                ]),
                                Part::Image => Value::map(vec![("type", Value::lit("image"))]),
                                Part::Video => Value::map(vec![("type", Value::lit("video"))]),
                            })
                            .collect(),
                    ),
                };
                e.push(("content".into(), content));
                if let Some(r) = &m.reasoning_content {
                    e.push(("reasoning_content".into(), Value::data(r)));
                }
                if let Some(n) = &m.name {
                    e.push(("name".into(), Value::data(n)));
                }
                if !m.tool_calls.is_empty() {
                    let calls = m
                        .tool_calls
                        .iter()
                        .map(|c| {
                            let args: Map = c
                                .arguments
                                .iter()
                                .map(|(k, v)| (k.clone(), json(v)))
                                .collect();
                            let function = Value::map(vec![
                                ("name", Value::data(&c.name)),
                                ("arguments", Value::Map(Rc::new(args))),
                            ]);
                            Value::map(vec![
                                ("type", Value::lit("function")),
                                ("function", function),
                            ])
                        })
                        .collect();
                    e.push(("tool_calls".into(), Value::list(calls)));
                }
                Value::Map(Rc::new(e))
            })
            .collect(),
    )
}

/// `tools`, in transformers' shape: `{"type": "function", "function": {"name",
/// "description", "parameters"}}`; none without any, as transformers passes
pub fn tools(tools: &[Tool]) -> Value {
    if tools.is_empty() {
        return Value::None;
    }
    Value::list(
        tools
            .iter()
            .map(|t| {
                let mut f = vec![("name", Value::data(&t.name))];
                if let Some(d) = &t.description {
                    f.push(("description", Value::data(d)));
                }
                f.push(("parameters", json(&t.parameters)));
                Value::map(vec![
                    ("type", Value::lit("function")),
                    ("function", Value::map(f)),
                ])
            })
            .collect(),
    )
}

/// A flag the template tests for being defined: `None` leaves it undefined
pub fn opt_bool(b: Option<bool>) -> Value {
    b.map_or(Value::Undefined, Value::Bool)
}

/// A string parameter, `None` leaving it undefined
pub fn opt_str(s: Option<&str>) -> Value {
    s.map_or(Value::Undefined, Value::data)
}

// ---------------------------------------------------------------------------
// JSON text

impl Json {
    pub fn parse(text: &str) -> R<Json> {
        let mut p = Parser {
            b: text.as_bytes(),
            i: 0,
        };
        let v = p.value()?;
        p.ws();
        if p.i != p.b.len() {
            return err(format!("trailing characters at {}", p.i));
        }
        Ok(v)
    }

    /// The value of key `k` of an object
    pub fn get(&self, k: &str) -> Option<&Json> {
        match self {
            Json::Object(o) => o.iter().find(|(key, _)| key == k).map(|(_, v)| v),
            _ => None,
        }
    }

    pub fn as_str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }
}

struct Parser<'a> {
    b: &'a [u8],
    i: usize,
}

impl Parser<'_> {
    fn ws(&mut self) {
        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }

    fn eat(&mut self, c: u8) -> bool {
        self.ws();
        if self.b.get(self.i) == Some(&c) {
            self.i += 1;
            true
        } else {
            false
        }
    }

    fn bad<T>(&self, what: &str) -> R<T> {
        err(format!("bad JSON at {}: {what}", self.i))
    }

    fn value(&mut self) -> R<Json> {
        self.ws();
        match self.b.get(self.i) {
            Some(b'{') => {
                self.i += 1;
                let mut m: Vec<(String, Json)> = Vec::new();
                if self.eat(b'}') {
                    return Ok(Json::Object(m));
                }
                loop {
                    self.ws();
                    let k = self.string()?;
                    if !self.eat(b':') {
                        return self.bad("expected ':'");
                    }
                    let v = self.value()?;
                    match m.iter_mut().find(|(key, _)| *key == k) {
                        Some((_, old)) => *old = v,
                        None => m.push((k, v)),
                    }
                    if self.eat(b'}') {
                        return Ok(Json::Object(m));
                    }
                    if !self.eat(b',') {
                        return self.bad("expected ',' or '}'");
                    }
                }
            }
            Some(b'[') => {
                self.i += 1;
                let mut l = Vec::new();
                if self.eat(b']') {
                    return Ok(Json::Array(l));
                }
                loop {
                    l.push(self.value()?);
                    if self.eat(b']') {
                        return Ok(Json::Array(l));
                    }
                    if !self.eat(b',') {
                        return self.bad("expected ',' or ']'");
                    }
                }
            }
            Some(b'"') => Ok(Json::Str(self.string()?)),
            Some(b't') if self.b[self.i..].starts_with(b"true") => {
                self.i += 4;
                Ok(Json::Bool(true))
            }
            Some(b'f') if self.b[self.i..].starts_with(b"false") => {
                self.i += 5;
                Ok(Json::Bool(false))
            }
            Some(b'n') if self.b[self.i..].starts_with(b"null") => {
                self.i += 4;
                Ok(Json::Null)
            }
            Some(b'-' | b'0'..=b'9') => {
                let start = self.i;
                let mut float = false;
                while let Some(&c) = self.b.get(self.i) {
                    match c {
                        b'0'..=b'9' | b'-' | b'+' => {}
                        b'.' | b'e' | b'E' => float = true,
                        _ => break,
                    }
                    self.i += 1;
                }
                let t = core::str::from_utf8(&self.b[start..self.i]).unwrap();
                if !float && let Ok(i) = t.parse::<i64>() {
                    return Ok(Json::Int(i));
                }
                match t.parse::<f64>() {
                    Ok(f) => Ok(Json::Float(f)),
                    Err(_) => self.bad("bad number"),
                }
            }
            _ => self.bad("expected a value"),
        }
    }

    fn string(&mut self) -> R<String> {
        if self.b.get(self.i) != Some(&b'"') {
            return self.bad("expected a string");
        }
        self.i += 1;
        let mut out = String::new();
        loop {
            let start = self.i;
            while self.i < self.b.len() && !matches!(self.b[self.i], b'"' | b'\\') {
                self.i += 1;
            }
            let chunk = core::str::from_utf8(&self.b[start..self.i])
                .map_err(|_| Error("bad UTF-8".to_string()))?;
            out.push_str(chunk);
            match self.b.get(self.i) {
                Some(b'"') => {
                    self.i += 1;
                    return Ok(out);
                }
                Some(b'\\') => {
                    self.i += 1;
                    let c = match self.b.get(self.i) {
                        Some(b'"') => '"',
                        Some(b'\\') => '\\',
                        Some(b'/') => '/',
                        Some(b'b') => '\u{8}',
                        Some(b'f') => '\u{c}',
                        Some(b'n') => '\n',
                        Some(b'r') => '\r',
                        Some(b't') => '\t',
                        Some(b'u') => {
                            let hex = |p: &mut Self| -> R<u32> {
                                let h =
                                    p.b.get(p.i + 1..p.i + 5).ok_or(Error("short \\u".into()))?;
                                p.i += 4;
                                u32::from_str_radix(core::str::from_utf8(h).unwrap_or("x"), 16)
                                    .map_err(|_| Error("bad \\u".into()))
                            };
                            let u = hex(self)?;
                            let u = if (0xd800..0xdc00).contains(&u)
                                && self.b.get(self.i + 1..self.i + 3) == Some(b"\\u")
                            {
                                self.i += 2;
                                let lo = hex(self)?;
                                0x10000 + ((u - 0xd800) << 10) + (lo - 0xdc00)
                            } else {
                                u
                            };
                            char::from_u32(u).unwrap_or('\u{fffd}')
                        }
                        _ => return self.bad("bad escape"),
                    };
                    self.i += 1;
                    out.push(c);
                }
                _ => return self.bad("unterminated string"),
            }
        }
    }
}
